Description['eal0001-exrzb2'] = "<LOC Unit_Description_900054> Disruptor Amplifier\n\n+8000 Health\n+30 Armor Regen\nDisruptor Damage 304 (+240)\nDisruptor Range 45 (+15)"
Description['eal0001-exles1'] = "<LOC Unit_Description_900055> Improved Engineering\nThis is a standard engineering enhancement system that focuses on improving resource allocation subsystems and armor strength.\n\nUnlock Tech 2 Construction\n+2000 Health\n+10 Armor Regen\n+16 Build Speed\n+6 Mass Production\n+900 Energy Production"
